### A* Path Search Algorithm

The A* algorithm has the following components:

1. **Graph Representation**: We represent the graph using an adjacency list.
2. **Heuristic**: We use a heuristic function to estimate the cost from the current node to the goal.
3. **Priority Queue**: We use a priority queue to get the next node to evaluate.
4. **Open and Closed Sets**: We keep track of the nodes to be evaluated and the nodes that have already been evaluated using two sets: `open_set` and `closed_set`.

Here is the implementation:

```python
import heapq

class Node:
    def __init__(self, state, parent=None, action=None, cost=0, heuristic=0):
        self.state = state
        self.parent = parent
        self.action = action
        self.cost = cost
        self.heuristic = heuristic
        self.g = self.cost  # Cost from start node to this node
        self.f = self.g + self.heuristic  # Estimated total cost from start to goal

    def __lt__(self, other):
        return self.f < other.f

def heuristic(state, goal_state):
    """Heuristic function (e.g., Manhattan distance)"""
    def distance(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    return sum(distance(state[i], goal_state[i]) for i in range(len(state)))

def get_neighbors(node, graph):
    """Get the neighbors of a node in the graph."""
    row, col = node.state
    neighbors = []
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        neighbor_row, neighbor_col = row + dr, col + dc
        if 0 <= neighbor_row < len(graph) and 0 <= neighbor_col < len(graph[0]) and graph[neighbor_row][neighbor_col] != 'X':
            neighbors.append((neighbor_row, neighbor_col))
    return neighbors

def reconstruct_path(came_from, current):
    path = []
    while current in came_from:
        current = came_from[current]
        path.append(current)
    path.reverse()
    return path

def a_star_search(graph, start, goal):
    open_set = []
    heapq.heappush(open_set, Node(start, None, None, 0, heuristic(start, goal)))
    closed_set = set()

    came_from = {}
    cost_so_far = {}
    cost_so_far[start] = 0

    while open_set:
        current = heapq.heappop(open_set)
        if current.state == goal:
            return reconstruct_path(came_from, current)

        closed_set.add(current.state)

        for neighbor in get_neighbors(current.state, graph):
            new_cost = cost_so_far[current.state] + 1
