Here's a basic implementation of DFS to find a path from a start node to a goal node in a graph represented as an adjacency list:

```python
class Graph:
    def __init__(self):
        self.graph = {}

    def add_edge(self, u, v):
        if u not in self.graph:
            self.graph[u] = []
        if v not in self.graph:
            self.graph[v] = []
        self.graph[u].append(v)

    def dfs(self, start, goal, path=None):
        if path is None:
            path = [start]
        if start == goal:
            return path
        for neighbor in self.graph[start]:
            if neighbor not in path:
                new_path = self.dfs(neighbor, goal, path + [neighbor])
                if new_path:
                    return new_path
        return None

