        if u in self.graph:
            self.graph[u].append(v)
        else:
            self.graph[u] = [v]

    def dfs(self, start, goal):
        visited = set()
        stack = [(start, [start])]  # Each element in the stack is a tuple (current node, path)

        while stack:
            (node, path) = stack.pop()
            if node not in visited:
                visited.add(node)
                if node == goal:
                    return path
                for neighbor in self.graph.get(node, []):
                    if neighbor not in visited:
                        stack.append((neighbor, path + [neighbor]))
        return None

